//! 📦️ Typed default cursor backing is retained before separate pure initialization and output handoff.
use super::*;
use semio_framework_value_native_storage::NativeOwnedStorage;
pub struct NativeDefaultSlot<T:NativeDefault>{cursor:NativeOwnedStorage<T::Cursor>,retired_header:Option<Box<T::Cursor>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,action:semio_framework_value_native_receiver_protocol::NativeReceivingChild,closing:bool}
impl<T:NativeDefault> NativeDefaultSlot<T>{
 pub fn new()->Self{Self{cursor:NativeOwnedStorage::empty(),retired_header:None,output:ManuallyDrop::new(None),retirement:Default::default(),action:Default::default(),closing:false}}
 pub fn ready(&self)->bool{!self.closing&&self.output.is_some()}
 pub fn demands(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}if let Some(d)=self.action.demand{return Ok(d)}if !self.cursor.reserved(){return Ok(NativeOwnedStorage::<T::Cursor>::reserve_demand())}if !self.cursor.initialized(){return Ok(NativeOwnedStorage::<T::Cursor>::seed_demand())}let cursor=self.cursor.get().ok_or_else(||ValueError::invariant("get target absent"))?;if cursor.output_ready(){nested(fixed(0),0)}else{nested(cursor.demands(body,maximum_work_units)?,0)}}
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{semio_framework_value_native_receiver_protocol::native_receive_zero_work!(maximum_work_units);let mut work=0;let result=(||{let d=self.demands(body,maximum_work_units)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.action.demand.is_none(){control.checkpoint()?;receiving_capacity(control,d.capacity_bytes)?;}if !self.cursor.reserved()||self.action.tag==2{self.action.tag=2;let units=self.action.work.unwrap_or_else(||self.cursor.reserve_work_demand());let turn=self.action.poll(control,d,g,units,maximum_work_units,|_,effect|self.cursor.reserve_empty(effect));work=turn.work;return turn.result}if !self.cursor.initialized()||self.action.tag==3{self.action.tag=3;let units=self.action.work.unwrap_or_else(||self.cursor.seed_work_demand());let turn=self.action.poll(control,d,g,units,maximum_work_units,|_,effect|self.cursor.initialize_seed(effect,||Ok(T::default_cursor())));work=turn.work;return turn.result}let cursor=self.cursor.get_mut().ok_or_else(||ValueError::invariant("get_mut target absent"))?;if cursor.output_ready(){let turn=cursor.take(child_grant(g,0));work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.output=Some(value);return Ok(RetainedCloneStep::Complete(p))}let turn=cursor.advance(control,body,maximum_work_units,child_grant(g,0));work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))})();RetainedWorkOutcome{result,work}}
 semio_framework_value_native_receiver_protocol::native_owned_public_output!(T,invalid,ready);
 pub fn begin_close(&mut self){self.closing=true;if let Some(cursor)=self.cursor.get_mut(){cursor.begin_close();}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if let Some(cursor)=self.retired_header.as_ref(){if !cursor.terminal_is_empty(){return Err(invalid())}return Ok(RetirementDemand{release_bytes:std::alloc::Layout::new::<T::Cursor>().size(),depth:1,..Default::default()})}if self.cursor.reserved(){if let Some(cursor)=self.cursor.get(){if !cursor.terminal_is_empty(){return nested(cursor.close_demands(body)?,0)}return Ok(NativeOwnedStorage::<T::Cursor>::move_demand())}return Ok(self.cursor.release_demand())}if self.action.failure.is_some(){return self.action.failure_demand(&self.retirement,body)}self.retirement.next_owner_demands::<T>(self.output.is_some(),&None,body)}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if self.retired_header.is_some(){return Ok(1)}if self.cursor.reserved(){if let Some(cursor)=self.cursor.get(){if !cursor.terminal_is_empty(){return cursor.close_work_demand(body)}}return Ok(1)}if self.action.failure.is_some(){return self.action.failure_work(&self.retirement,body)}self.retirement.next_owner_work::<T>(self.output.is_some(),&None,body)}
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();if self.action.pending(){return RetainedWorkOutcome{result:Err(invalid().into()),work:0}}if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if self.retired_header.is_some(){let layout=std::alloc::Layout::new::<T::Cursor>();let pointer=Box::into_raw(match self.retired_header.take(){Some(v)=>v,None=>return RetainedWorkOutcome{result:Err(ValueError::invariant("retired_header absent").into()),work:0}});if layout.size()!=0{unsafe{std::alloc::dealloc(pointer.cast(),layout)}}return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()})),work:1}}if self.cursor.reserved(){if let Some(cursor)=self.cursor.get_mut().filter(|c|!c.terminal_is_empty()){let turn=cursor.close_step(&mut effect.reborrow(child_grant(g,0),effect.maximum_work_units()).expect("retirement child exceeds original effect"));return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}}if self.cursor.initialized(){let turn=self.cursor.take_box(g);let work=turn.work;let result=turn.result.map(|value|if let Some((owner,p))=value{self.retired_header=Some(owner);RetainedCloneStep::Progress(p)}else{RetainedCloneStep::Progress(Default::default())}).map_err(Into::into);return RetainedWorkOutcome{result,work}}let turn=self.cursor.release(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}}if !self.retirement.is_empty(){return self.retirement.step_granted(effect)}if self.action.failure.is_some(){return self.action.close_failure(&mut self.retirement,effect)}let turn=self.retirement.begin_granted(&mut self.output,effect);RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work}}
 pub fn terminal_is_empty(&self)->bool{self.cursor.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.action.terminal_is_empty()}
}
impl<T:NativeDefault> Default for NativeDefaultSlot<T>{fn default()->Self{Self::new()}}
impl<T:NativeDefault> Drop for NativeDefaultSlot<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native default slot requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.output);ManuallyDrop::drop(&mut self.pending_cursor);}}}}
